(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12 + Math.sin((x+y)*0.008+t*0.4)*8;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.015+t*0.3)*12 + Math.cos((x-y)*0.01-t*0.35)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.03+t*0.5)*5 + Math.cos(sy*0.025-t*0.4)*4;
  const w2y = Math.cos(sy*0.028-t*0.45)*5 + Math.sin(sx*0.022+t*0.55)*4;
  const wx = sx+w2x, wy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.07,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.09,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.05,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.11,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.06,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.08,1.9],
    [200+Math.sin(t*1.1)*60,140+Math.cos(t*0.9)*40,0.15,3.2],
    [300+Math.cos(t*0.75)*70,100+Math.sin(t*1.0)*50,0.18,2.8],
    [80+Math.sin(t*0.65+3)*50,200+Math.cos(t*0.85+1)*45,0.13,3.5]
  ];
  let aS=0, iS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((wx-sX)**2+(wy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
  }
  const act=aS/9, inh=iS/9;
  const bg1=(Math.sin(wx*0.035+wy*0.02+t*0.7)+Math.sin(wx*0.025-wy*0.035+t*1.0))/2;
  const bg2=(Math.sin(wx*0.06+wy*0.05+t*1.3)+Math.sin(wx*0.05-wy*0.06+t*1.6))/2*0.5;
  const bg3=(Math.sin(wx*0.1+wy*0.08+t*2.2)+Math.sin(wx*0.08-wy*0.1+t*2.5))/2*0.25;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((wx-cx)**2+(wy-cy)**2), ang=Math.atan2(wy-cy,wx-cx);
  const sp1=(Math.sin(dist*0.045-ang*3-t*1.5)+Math.sin(dist*0.035+ang*4-t*1.2))*0.35;
  const c2x=240+Math.sin(t*0.2)*80, c2y=120+Math.cos(t*0.25)*60;
  const d2=Math.sqrt((wx-c2x)**2+(wy-c2y)**2), a2=Math.atan2(wy-c2y,wx-c2x);
  const sp2=(Math.sin(d2*0.05+a2*2-t*1.8)+Math.sin(d2*0.04-a2*5+t*1.0))*0.25;
  const c3x=240+Math.cos(t*0.15+2)*100, c3y=120+Math.sin(t*0.2+1)*70;
  const d3=Math.sqrt((wx-c3x)**2+(wy-c3y)**2), a3=Math.atan2(wy-c3y,wx-c3x);
  const sp3=(Math.sin(d3*0.055-a3*3+t*1.4)+Math.sin(d3*0.045+a3*6-t*0.9))*0.2;
  const raw=act-inh*0.65+bg*0.3+sp1+sp2+sp3;
  const r1=Math.tanh(raw*2.5), r2=Math.tanh((raw+Math.sin(act*2)*0.3)*3.0);
  const reaction=r1*0.6+r2*0.4;
  const cell=Math.tanh((Math.sin(wx*0.14)*Math.sin(wy*0.14)+Math.sin((wx+wy)*0.09+t)*0.4+Math.sin((wx-wy)*0.11-t*0.7)*0.3)*1.8)*0.25;
  const micro=Math.sin(wx*0.2+wy*0.18+t*3)*Math.sin(wx*0.15-wy*0.22-t*2.5)*0.15;
  const blend=reaction*0.6+cell*0.2+micro*0.2, v=blend*0.5+0.5;
  const pal=[
    [10,14,68],[18,45,98],[15,82,118],[20,135,125],
    [50,172,95],[140,190,60],[210,185,50],[225,155,45],
    [215,110,50],[195,70,58],[165,45,72],[120,30,88],
    [55,18,78],[10,14,68]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const intensity=Math.abs(reaction);
  const lum=0.72+intensity*0.28+Math.sin(reaction*Math.PI)*0.12;
  const edge=1.0+(intensity>0.6?(intensity-0.6)*1.4:0);
  const hs=Math.sin(ang*2+t*0.5)*0.06;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*(lum*edge)+hs*25)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*(lum*edge)+hs*12)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*(lum*edge)-hs*18)|0)
  ];
}
